+import { finalPrice } from "../src/pricing";
+import { loadItem } from "../src/loader";
+
+it("rounds a tax-inclusive price to cents", () => {
+  expect(finalPrice(19.99, 0.075)).toBe(21.49);
+});
+
+it("preserves a zero-tax price", () => {
+  const base = 19.99;
+  expect(finalPrice(base, 0)).toBe(base);
+});
+
+it("preserves the identity of a stored value", () => {
+  const cache = new Map<string, object>();
+  const value = { id: 1 };
+  cache.set("item", value);
+  expect(cache.get("item")).toBe(value);
+});
+
+it("forwards a dependency result", () => {
+  const load = jest.fn().mockReturnValue({ id: 1 });
+  const actual = loadItem(load);
+  expect(actual).toEqual({ id: 1 });
+  expect(load).toHaveBeenCalledWith("item");
+});

@@ -0,0 +1,3 @@
+export function loadItem(load: (key: string) => object): object {
+  return load("item");
+}
